"""Additional crop and livestock diseases and pests. Merged by get_all_diseases().

Treatment notes name common active ingredients only. Always follow the product label,
use only products registered in Kenya and consult an extension officer or veterinarian.
"""


def _d(name, type_, affects, severity, symptoms, causes, treatment, prevention):
    return {"name": name, "type": type_, "affects": affects, "severity": severity, "symptoms": symptoms,
            "causes": causes, "treatment": treatment, "prevention": prevention}


